def near(A,B,w):
    A={nf(x) for x in A}; B={nf(x) for x in B}; out=[]
    for b in books:
        ks=list(NT[b])
        for i,k in enumerate(ks):
            if {l for l,_,_ in NT[b][k]}&A and any({l for l,_,_ in NT[b][kk]}&B for kk in ks[max(0,i-w):i+w+1]): out.append(f'{b} {k[0]}:{k[1]}')
    return out
